<?php/** * 分词服务 */namespace app\api\service\public;use app\api\service\CommService;use Fukuball\Jieba\Finalseg;use Fukuball\Jieba\Jieba;class FenciService extends CommService{    public function __construct($param)    {        parent::_initialize($param);    }    public function doParticiple($word, $toJson = false, $mode = '')    {        ini_set('memory_limit', '1024M');        Jieba::init();        Finalseg::init();        $dict = CONF_PATH . 'dict/user_dict.txt';        Jieba::loadUserDict($dict); # $dict 為自定義詞典的絕對路徑        switch ($mode) {            case "search":                #搜索引擎模式                $seg_list = Jieba::cutForSearch($word);                break;            default:                #正常模式                $cut_all = true;  //#true全模式  false#默认精准模式                $seg_list = Jieba::cut($word, $cut_all);                break;        }        if ($toJson) {            return json_encode($seg_list, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);        }        return $seg_list;    }}